 static HttpRequest rq(String url,String method,String body,List<HttpHeader> hs){var uri=java.net.URI.create(url);return proxy(HttpRequest.class,(p,m,a)->switch(m.getName()){
  case "headerValue"->hs.stream().filter(h->h.name().equalsIgnoreCase(a[0].toString())).map(HttpHeader::value).findFirst().orElse(null);case "url"->url;case "method"->method;case "headers"->hs;case "parameters"->List.of();case "isInScope"->true;case "body"->bytes(body.getBytes(StandardCharsets.UTF_8));case "bodyToString"->body;
  case "toString"->method+" "+uri.getRawPath()+(uri.getRawQuery()==null?"":"?"+uri.getRawQuery())+" HTTP/1.1\r\n"+String.join("\r\n",hs.stream().map(HttpHeader::toString).toList())+"\r\n\r\n"+body;
  case "toByteArray"->bytes(p.toString().getBytes(StandardCharsets.UTF_8));
  case "withBody"->{List<HttpHeader> next=new ArrayList<>(hs);next.removeIf(h->h.name().equalsIgnoreCase("Content-Length"));next.add(header("Content-Length",Integer.toString(a[0].toString().getBytes(StandardCharsets.UTF_8).length)));yield rq(url,method,a[0].toString(),next);}case "withMethod"->rq(url,a[0].toString(),body,hs);
  case "withRemovedHeader"->{String name=a[0] instanceof HttpHeader h?h.name():a[0].toString();yield rq(url,method,body,hs.stream().filter(h->!h.name().equalsIgnoreCase(name)).toList());}
  case "withHeader"->{List<HttpHeader> next=new ArrayList<>(hs);String name=a[0].toString();next.removeIf(h->h.name().equalsIgnoreCase(name));next.add(header(name,a[1].toString()));yield rq(url,method,body,next);}
  default->def(m);
 });}
